function buscaBinaria(lista, alvo) {
  let baixo = 0;
  let alto = lista.length - 1;
  while (baixo <= alto) {
    const meio = Math.floor((baixo + alto) / 2);
    if (lista[meio] === alvo) return meio;
    if (lista[meio] < alvo) baixo = meio + 1;
    else alto = meio - 1;
  }
  return -1;
}
